  ctx.scale(size / 256, size / 256);
  ctx.fillStyle = color2;
  ctx.strokeStyle = color2;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";
  const grow = deterministicMath.max(0, stroke) * 256 / size;
