    ctx.fillRect(14, 40, 32, 2);
    ctx.fillStyle = "#ffeaa7";
    ctx.fillRect(26, 26, 8, 7);
    ctx.fillRect(27, 24, 6, 2);
    ctx.fillRect(22, 19, 3, 4);
    ctx.fillRect(27, 16, 4, 4);
    ctx.fillRect(33, 19, 3, 4);
    ctx.clearRect(42, 36, 6, 6);
