// game/scenes/Title.ts
var MENU_LEFT = 88;
var STORY_BUTTON_Y = 346;
var PLAYGROUND_BUTTON_Y = 466;
var TOKYO_X = 878;
var TOKYO_FEET_Y = 581;
var TOKYO_SCALE3 = 4;
var SEATED_FOOT_OFFSET = 21 * TOKYO_SCALE3;
var SEATED_FIRST_FRAME = 42;
var SEATED_FRAME_COUNT = 4;
function openStory() {
  prepareMobileDisplay();
  game.scenes.go("story");
}
function openPlayground() {
  prepareMobileDisplay();
  startPlayground();
}
var Title = {
  name: "title",
  enter() {
    game.touch.visible = false;
    game.camera.snap(game.screen.width / 2, game.screen.height / 2, 1);
    game.background.picture("title-home-dusk", "stretch");
    game.text("Tokyo\u2019s", MENU_LEFT, 140, {
      size: 102,
      font: "serif-bold",
      color: "#fff4d9",
      align: "left",
      shadow: { color: "#131d1a", x: 3, y: 4 }
    });
    game.text("Journey", MENU_LEFT, 240, {
      size: 112,
      font: "serif-bold",
      color: "#f3c37e",
      align: "left",
      shadow: { color: "#131d1a", x: 3, y: 4 }
    });
    game.ui.button({
      id: "choose-story",
      anchor: "top-left",
      x: MENU_LEFT,
      y: STORY_BUTTON_Y,
      h: MENU_BUTTON_HEIGHT,
      text: "Story Mode",
      icon: "book",
      iconSize: 29,
      onClick: openStory,
      style: menuButtonStyles.primary
    });
    game.text(
      "Start at home and follow Tokyo into her dream.",
      MENU_LEFT,
      435,
      { size: 19, font: "sans", color: "#f2e5cd", align: "left" }
    );
    game.ui.button({
      id: "choose-playground",
      anchor: "top-left",
      x: MENU_LEFT,
      y: PLAYGROUND_BUTTON_Y,
      h: MENU_BUTTON_HEIGHT,
      text: "Playground",
      icon: "paw",
      iconSize: 29,
      onClick: openPlayground,
      style: menuButtonStyles.secondary
    });
    game.text(
      "Explore the park at your own pace.",
      MENU_LEFT,
      555,
      { size: 19, font: "sans", color: "#f2e5cd", align: "left" }
    );
    if (!isMobileView()) {
      game.text(
        "2  Story Mode     Enter  Playground",
        MENU_LEFT,
        637,
        { size: 16, font: "mono", color: "#d8dac1", align: "left" }
      );
    }
    const rotateHint = isMobileView() ? game.text(
      "Turn your phone sideways for the best view",
      MENU_LEFT,
      680,
      { size: 18, font: "sans-bold", color: "#fff4d9", align: "left" }
    ) : null;
    game.ui.button({
      id: "settings-btn",
      anchor: "top-right",
      x: -80,
      y: 16,
      h: 56,
      style: "icon",
      icon: "settings",
      accessibleLabel: "Settings",
      onClick: () => game.scenes.push("settings")
    });
    addFullscreenButton({ anchor: "top-right", x: -16, y: 16 });
    game.spawn({
      id: "title-tokyo-shadow",
      texture: "shadow",
      x: TOKYO_X,
      y: TOKYO_FEET_Y,
      width: 148,
      layer: "world",
      alpha: 0.52
    });
    const tokyo = game.spawn({
      id: "title-tokyo",
      texture: "tokyo",
      frame: SEATED_FIRST_FRAME,
      x: TOKYO_X,
      y: TOKYO_FEET_Y - SEATED_FOOT_OFFSET,
      scale: TOKYO_SCALE3,
      layer: "world",
      z: 1
    });
    let elapsed = 0;
    game.step("title", (dt) => {
      elapsed += dt;
      if (rotateHint) rotateHint.visible = isPortrait();
      tokyo.setFrame(SEATED_FIRST_FRAME + deterministicMath.floor(elapsed * 2.5) % SEATED_FRAME_COUNT);
      if (game.touch.visible) game.touch.visible = false;
      if (game.input.keyPressed("Digit2")) {
        openStory();
      } else if (!game.ui.focus && (game.input.keyPressed("Enter") || game.input.keyPressed("Space"))) {
        openPlayground();
      }
    });
  }
};

// game/scenes/Play.ts
var STATES2 = ["idle", "walking", "running", "jumping", "crouching", "sitting", "pooping"];
var Play = {
  name: "meadow",
  enter() {
    run.scene = "meadow";
    game.touch.visible = getTouchOverride() ?? isMobileView();
    spawnMeadow();
    game.physics.gravity(0, 1500);
    const treats = spawnTreats((collected, total) => {
      const all = collected >= total;
      treatCounter.text = all ? `\u2605 ALL ${total} TREATS COLLECTED! \u{1F6A9}` : `TREATS: ${collected} / ${total}`;
      treatCounter.color = all ? "#ffeaa7" : "#ffd56b";
    });
    const tokyo = spawnTokyo(run.spawnX, GROUND_Y);
    game.rig.follow(tokyo);
    game.rig.bounds({ x: 0, y: 0, w: MEADOW_WIDTH, h: 720 });
    game.rig.deadzone = { w: 160, h: 260 };
    game.rig.smoothing = 0.12;
    game.rig.offset = { x: 90, y: -100 };
    game.rig.lookAhead = 0.2;
    const shadow = game.spawn({
      id: "tokyo-shadow",
      texture: "shadow",
      x: run.spawnX,
      y: GROUND_Y - 2,
      layer: "world",
      z: 1,
      alpha: 0.25
    });
    game.text("TOKYO'S JOURNEY", 40, 40, { size: 30, font: "mono-bold", color: "#34483e", align: "left" });
    game.text("01 / THE MOVEMENT MEADOW", 42, 76, { size: 16, font: "mono", color: "#5c705b", align: "left" });
    game.text("A golden girl. A little adventure.", 42, 104, { size: 16, font: "mono", color: "#657760", align: "left" });
    game.spawn({ id: "treat-hud-icon", texture: "treat-icon", layer: "hud", x: 54, y: 142, z: 12 });
    const treatCounter = game.text(`TREATS: ${treats.collected} / ${treats.total}`, 74, 134, {
      size: 18,
      font: "mono-bold",
      color: "#ffd56b",
      align: "left",
      layer: "hud",
      shadow: { color: "#253c36", x: 2, y: 2 }
    });
    game.ui.pauseButton();
    game.ui.muteButton();
    const fsBtn = addFullscreenButton({ anchor: "top-right", x: -152, y: 16 });
    game.ui.button({
      id: "settings-btn",
      anchor: "top-right",
      x: -216,
      y: 16,
      w: 56,
      h: 56,
      style: "icon",
      icon: "settings",
      accessibleLabel: "Settings",
      onClick: () => game.scenes.push("settings")
    });
    addRotateButton({ anchor: "top-right", x: -280, y: 16 });
    const footer = game.graphics({ layer: "hud" });
    footer.draw((ctx) => {
      ctx.fillStyle = "#253c36";
      ctx.fillRect(0, 618, 1280, 102);
      ctx.fillStyle = "#c4d098";
      ctx.fillRect(0, 618, 1280, 3);
    });
    const labels = STATES2.map((state, index) => game.text(
      state.toUpperCase(),
      250 + index * 130,
      647,
      { size: 17, font: "mono-bold", color: "#81958b", align: "center" }
    ));
    const hintsLabel = game.text("", 640, 690, { size: 15, font: "mono", color: "#c3d1b2", align: "center" });
    const telemetry = game.text("", 1228, 648, { size: 16, font: "mono-bold", color: "#e4ca7c", align: "right" });
    game.step("meadow-hud", () => {
      if (game.controls.justPressed("pause")) {
        game.scenes.push("pause");
        return;
      }
      if (game.input.keyPressed("KeyR")) {
        run.spawnX = 220;
        game.scenes.go("meadow");
        return;
      }
      if (getTouchOverride() === null) {
        const shouldShow = isMobileView();
        if (game.touch.visible !== shouldShow) game.touch.visible = shouldShow;
      }
      if (fsBtn?.alive) {
        fsBtn.ui.icon = game.commands.isFullscreen ? "fullscreen-exit" : "fullscreen";
      }
      labels.forEach((label, index) => {
        label.color = STATES2[index] === tokyo.data.state ? "#f4d888" : "#81958b";
      });
      const settings = getSettings();
      hintsLabel.text = game.touch.visible ? `ARROWS MOVE / CROUCH / STAND   \u2022   JUMP   \u2022   RUN [${settings.runBehavior.toUpperCase()}]   \u2022   SIT   \u2022   POOP` : `A/D WALK   SHIFT RUN [${settings.runBehavior.toUpperCase()}]   SPACE JUMP   DOWN/C CROUCH [${settings.crouchBehavior.toUpperCase()}]   E SIT   G POOP   R RESET`;
      telemetry.text = `${deterministicMath.round(deterministicMath.abs(tokyo.data.vx))} px/s`;
      shadow.x = tokyo.x;
      shadow.y = GROUND_Y - 2;
      shadow.alpha = deterministicMath.max(0, 0.25 - deterministicMath.max(0, GROUND_Y - tokyo.data.feet) / 800);
    }, { after: "tokyo-visual" });
  },
  exit() {
    game.touch.visible = false;
  }
};

// game/scenes/Pause.ts
var Pause = {
  name: "pause",
  enter() {
    game.touch.visible = false;
    const W = game.screen.width, H = game.screen.height;
    game.ui.panel({ anchor: "center", w: W, h: H, z: 20, safeArea: false, style: "dark" });
    const menu = game.ui.window({ anchor: "center", z: 21, w: deterministicMath.min(W - 96, 460), h: "auto", title: "Paused", titleHeight: 56, layout: { padding: 24, gap: 14, align: "stretch" } });
    game.ui.button({ parent: menu, h: 80, text: "Resume", style: "good", icon: "play", onClick: () => game.scenes.pop() });
    game.ui.button({ parent: menu, h: 72, text: "Settings", icon: "settings", onClick: () => game.scenes.push("settings") });
    const fsMenuItem = game.ui.button({
      parent: menu,
      h: 72,
      text: game.commands.isFullscreen ? "Exit Fullscreen" : "Fullscreen",
      icon: game.commands.isFullscreen ? "fullscreen-exit" : "fullscreen",
      onClick: async (b) => {
        await game.commands.fullscreen();
        if (b && "ui" in b) {
          b.ui.text = game.commands.isFullscreen ? "Exit Fullscreen" : "Fullscreen";
          b.ui.icon = game.commands.isFullscreen ? "fullscreen-exit" : "fullscreen";
        }
      }
    });
    game.ui.button({ parent: menu, h: 72, text: "Restart", icon: "restart", onClick: () => {
      if (run.scene === "play") startPlayground();
      else if (run.scene === "home") game.scenes.go("home");
      else if (run.scene === "journey") game.scenes.go(journey.stage === 1 ? "dream-start" : "journey");
      else {
        run.spawnX = 220;
        game.scenes.go("meadow");
      }
    } });
    game.ui.button({ parent: menu, h: 72, text: "Title", icon: "home", onClick: () => game.scenes.go("title") });
    game.ui.muteButton({ z: 24 });
    menu.ui.y = -H;
    game.tween.to(menu.ui, { y: 0 }, { duration: 0.35, ease: "easeOutBack" });
    game.step("pause", () => {
      if (fsMenuItem?.alive) {
        fsMenuItem.ui.text = game.commands.isFullscreen ? "Exit Fullscreen" : "Fullscreen";
        fsMenuItem.ui.icon = game.commands.isFullscreen ? "fullscreen-exit" : "fullscreen";
      }
      if (game.input.keyPressed("Escape") || game.input.keyPressed("KeyP")) game.scenes.pop();
    });
  },
  exit() {
    if (isMobileView()) {
      game.touch.visible = true;
    }
  }
};

