    const tokyo = spawnTokyo(run.spawnX, PARK_GROUND);
    const activities = spawnParkActivities();
    game.rig.follow(tokyo);
    game.rig.bounds({ x: 0, y: 0, w: PARK_WIDTH, h: 720 });
